// Handles every tank: subscribe to lpg/+/alert and lpg/+/info
const base = msg.topic.replace(/\/(alert|info)$/, '');
const tanks = flow.get('lpgTanks') || {};

if (msg.topic.endsWith('/info')) {            // tank name + suppliers (retained)
    tanks[base] = msg.payload;
    flow.set('lpgTanks', tanks);
    return null;
}
if (msg.retain) return null;                  // old state replayed on (re)connect - no email

const info = tanks[base] || {};
const name = info.tank || base;
let body;
if (msg.payload === 'low') {
    msg.topic = 'LPG level low: ' + name;
    body = 'The gas level in ' + name + ' has dropped below ' +
           (info.low_alert_pct ? info.low_alert_pct + '%' : 'the warning level') +
           '.\n\nTime to arrange a refill.';
    (info.suppliers || []).forEach((s, n) => {
        body += '\n\n' + (n ? 'Alternative' : 'Preferred') + ' supplier: ' + (s.name || '');
        if (s.phone)   body += '\nPhone: ' + s.phone;
        if (s.email)   body += '\nEmail: ' + s.email;
        if (s.web)     body += '\nWebsite: ' + s.web;
        if (s.account) body += '\nAccount number: ' + s.account;
        if (s.address) body += '\nAddress: ' + s.address.replace(/\n/g, ', ');
    });
} else if (msg.payload === 'ok') {
    msg.topic = 'LPG level back to normal: ' + name;
    body = 'The gas level in ' + name + ' is back above the warning level.';
} else {
    return null;
}
if (info.url) body += '\n\nTank status page: ' + info.url;
msg.payload = body;
return msg;
